-- Starter content for Varanasi (Kashi). Image and source URLs are left empty on purpose:
-- add them through PUT /api/places/{id} once you have images you are allowed to use.

INSERT INTO places (name, type, short_description, description) VALUES
('Dashashwamedh Ghat', 'GHAT',
 'The main and busiest ghat of Varanasi, famous for the grand evening Ganga Aarti.',
 'Dashashwamedh Ghat is the most famous ghat in Varanasi and lies close to the Kashi Vishwanath Temple. Every evening priests perform the Ganga Aarti here with lamps, conch shells and chanting, and crowds gather on the steps and on boats to watch. According to tradition the name refers to a ten-horse sacrifice performed by Brahma. Boat rides, rituals, flower sellers and street life keep the ghat busy from early morning until late at night.'),
('Assi Ghat', 'GHAT',
 'The southernmost major ghat, where the Assi stream meets the Ganga, loved for its calm sunrises.',
 'Assi Ghat marks the southern end of the main line of ghats. It is popular with students, artists and travellers, and is known for morning gatherings with music, yoga and prayers at sunrise. It is quieter than Dashashwamedh Ghat and has many cafes and guesthouses nearby, which makes it a comfortable place to spend a slow morning by the river.'),
('Manikarnika Ghat', 'GHAT',
 'The most important cremation ghat of Varanasi, where the fires are said to burn day and night.',
 'Manikarnika Ghat is regarded as the principal cremation ground of Kashi. Hindu belief holds that cremation here helps the departed attain moksha, liberation from the cycle of birth and death. Visitors should be respectful: it is a place of mourning and ritual, and photography is generally not appreciated. It can be seen quietly from the river or from a distance.'),
('Harishchandra Ghat', 'GHAT',
 'One of the two main cremation ghats, named after the legendary King Harishchandra.',
 'Harishchandra Ghat is named after King Harishchandra, who is remembered in Indian tradition for his devotion to truth. Like Manikarnika Ghat it is used for Hindu cremations, and it also has an electric crematorium. It is a solemn place and is best visited with sensitivity and without intrusive photography.'),
('Panchganga Ghat', 'GHAT',
 'A ghat believed to be where five sacred rivers meet, with steep steps rising to a hilltop mosque.',
 'Panchganga Ghat is believed to be the meeting point of five rivers: the Ganga, Yamuna, Saraswati, Kirana and Dhutapapa. Only the Ganga is visible today. Tall steps lead up from the water and a large mosque overlooks the ghat, giving it one of the most recognisable skylines on the riverfront. Many pilgrims bathe here early in the morning, especially during the month of Kartik.'),
('Kedar Ghat', 'GHAT',
 'A ghat known for the Kedareshwar temple and its distinctive striped steps.',
 'Kedar Ghat takes its name from the Kedareshwar temple dedicated to Lord Shiva, which stands above the steps. It is especially popular with pilgrims from South India. The steps are painted in bold stripes, and the ghat is a pleasant place to watch pilgrims, priests and boats while taking a walk along the river.'),
('Tulsi Ghat', 'GHAT',
 'A ghat named after the saint-poet Tulsidas, author of the Ramcharitmanas.',
 'Tulsi Ghat is associated with Goswami Tulsidas, the saint-poet who wrote the Ramcharitmanas, the Hindi retelling of the Ramayana. The ghat is a quiet stretch of the riverfront with wide steps, and it has long been linked with literature, devotion and the cultural life of Varanasi.'),
('Lalita Ghat', 'GHAT',
 'A ghat best known for the wooden Nepali Temple that rises above its steps.',
 'Lalita Ghat is known for the Nepali Temple, built in the Nepalese style with carved wood and a pagoda-like roof, and dedicated to Lord Shiva. The temple shows the long connection between Kashi and Nepal. The ghat is a good place for photographers who enjoy architecture and river views away from the busiest crowds.'),
('Kashi Vishwanath Temple', 'TEMPLE',
 'One of the twelve Jyotirlinga shrines of Lord Shiva and the spiritual heart of Varanasi.',
 'The Kashi Vishwanath Temple is dedicated to Lord Shiva as Vishweshwara, the Lord of the Universe, and is one of the twelve Jyotirlingas. The present temple was built in the 18th century by Maharani Ahilyabai Holkar of Indore, and its spires are covered in gold. The Kashi Vishwanath Corridor, opened in 2021, links the temple to the Ganga ghats. Security checks are strict and darshan rules and timings change, so check the latest guidance before you go.'),
('Sankat Mochan Hanuman Temple', 'TEMPLE',
 'A much-loved Hanuman temple in south Varanasi, busiest on Tuesdays and Saturdays.',
 'Sankat Mochan means remover of troubles. This temple is dedicated to Lord Hanuman and is traditionally said to have been established by Tulsidas. It stands in a green compound in the southern part of the city and draws large crowds on Tuesdays and Saturdays. Devotees commonly offer sweets such as besan laddus, and the temple is known for its annual music festival.'),
('Durga Temple', 'TEMPLE',
 'A red stone temple beside a sacred tank, often called the Monkey Temple.',
 'The Durga Temple, also called Durga Kund Temple, is dedicated to Goddess Durga. It is built in the north Indian Nagara style around a rectangular tank known as Durga Kund and is painted in deep red. Monkeys live in the area, so the temple is often called the Monkey Temple. It is especially crowded during Navratri.'),
('Tulsi Manas Temple', 'TEMPLE',
 'A white marble temple with verses of the Ramcharitmanas engraved on its walls.',
 'The Tulsi Manas Temple was built in 1964 in white marble and is dedicated to Lord Rama. Verses of the Ramcharitmanas by Tulsidas are inscribed on its walls, and the temple stands near the Durga Temple. It is a calm place to visit and easy to combine with a trip to the neighbouring temples.'),
('New Vishwanath Temple', 'TEMPLE',
 'A large marble temple on the Banaras Hindu University campus, open to all visitors.',
 'The New Vishwanath Temple stands inside the Banaras Hindu University campus. It was envisioned by Pandit Madan Mohan Malaviya, the founder of the university, and is built in marble in a style inspired by the Kashi Vishwanath Temple. It is open to visitors of all backgrounds and is known for its peaceful setting among the university gardens.'),
('Kal Bhairav Temple', 'TEMPLE',
 'The temple of Kal Bhairav, the traditional guardian and Kotwal of Kashi.',
 'Kal Bhairav is regarded as the Kotwal, or chief guardian, of Kashi. Devotees traditionally seek his blessings before or after visiting the Kashi Vishwanath Temple. The temple is in the old city, and a visit gives a good sense of the narrow lanes and everyday devotion of Varanasi.'),
('Annapurna Devi Temple', 'TEMPLE',
 'A temple of Goddess Annapurna, the giver of food, close to Kashi Vishwanath.',
 'The Annapurna Devi Temple is dedicated to Goddess Annapurna, regarded as the provider of food and nourishment. It stands close to the Kashi Vishwanath Temple in the old city, and many pilgrims visit both on the same day. The goddess is closely linked with the idea that no one in Kashi should go hungry.'),
('Bharat Mata Temple', 'TEMPLE',
 'A unique temple with a marble relief map of India instead of a deity.',
 'The Bharat Mata Temple is dedicated to Mother India. Instead of a statue it holds a large marble relief map of undivided India showing mountains, rivers and plains. It was inaugurated by Mahatma Gandhi in 1936 and is part of the Mahatma Gandhi Kashi Vidyapith campus.');
